class OrdersRepository {
  OrdersRepository(this._db, this._api);

  final LocalDb _db;
  final OrdersApi _api;

  /// The UI watches this. It emits immediately from disk and never awaits
  /// the network, so a cold start on a dead connection still shows orders.
  Stream<List<Order>> watch() => _db.watchOrders();

  Future<void> setStatus(String id, OrderStatus status) async {
    // Apply locally first; the screen updates on this frame.
    await _db.upsert(id, (o) => o.copyWith(status: status, dirty: true));
    await _db.enqueue(Mutation.status(id, status));
    unawaited(sync());
  }

  Future<void> sync() async {
    for (final mutation in await _db.pendingMutations()) {
      try {
        final server = await _api.apply(mutation);
        await _db.upsert(server.id, (_) => server.copyWith(dirty: false));
        await _db.dequeue(mutation.id);
      } on ConflictException catch (e) {
        // Two devices changed this while both were offline. The rule is a
        // product decision, written down here rather than left to chance.
        await _db.upsert(e.serverOrder.id, (_) => e.serverOrder);
        await _db.dequeue(mutation.id);
      } on SocketException {
        return; // still offline; the queue keeps its order for next time
      }
    }
  }
}
